export const THUNDER={title:'Thunder',author:'MorningGloryProductions',src:'https://cdn.freesound.org/previews/195/195344_3633506-hq.mp3',source:'https://freesound.org/people/MorningGloryProductions/sounds/195344/',license:'CC0'};let thunderPlayer=null,thunderTimer=null;
export const TRACKS=[{title:'Monkeys Spinning Monkeys',src:'https://incompetech.com/music/royalty-free/mp3-royaltyfree/Monkeys%20Spinning%20Monkeys.mp3',source:'https://incompetech.com/music/royalty-free/index.html?isrc=USUAN1400011'},{title:'Carefree',src:'https://incompetech.com/music/royalty-free/mp3-royaltyfree/Carefree.mp3',source:'https://incompetech.com/music/royalty-free/index.html?isrc=USUAN1400037'},{title:'Fluidscape',src:'https://incompetech.com/music/royalty-free/mp3-royaltyfree/Fluidscape.mp3',source:'https://incompetech.com/music/royalty-free/index.html?isrc=USUAN1100393'}];
let bgMedia=null,bgIndex=-1,speechDone=null;let narration=true;export const narrationEnabled=()=>narration;export function setNarration(on){narration=on;if(!on){window.speechSynthesis?.cancel();speechDone?.();}}
