export const isEnabled=()=>enabled;
export function setVolume(value){volume=Math.min(1,Math.max(0,value));applyVolume();}
export const getVolume=()=>volume;
export function musicEra(s){const a=Math.floor(s.day/365);return s.retired?'归田':a<6?'童梦':a<18?'青葱':s.stage!=='work'?'求索':a<60?'山河':'岁华';}
export function syncBackground(s){const next=musicEra(s);if(next!==background){stopBackground();for(const [o,bus] of activeNodes){if(bus==='background'){try{o.stop();}catch{}activeNodes.delete(o);}}background=next;if(timer){clearTimeout(timer);timer=null;}if(enabled)loopBackground();}if(s.ended){stopBackground();background='';if(timer){clearTimeout(timer);timer=null;}}}
function tone(note,start,duration,bus,type='sine',gain=.08,root=261.63){const o=ctx.createOscillator(),g=ctx.createGain();o.type=type;o.frequency.value=root*2**(note/12);const t=ctx.currentTime+start;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(gain,t+.03);g.gain.exponentialRampToValueAtTime(.0001,t+duration);o.connect(g);g.connect(buses[bus]);o.start(t);o.stop(t+duration+.03);activeNodes.set(o,bus);o.onended=()=>{activeNodes.delete(o);o.disconnect();g.disconnect();};}
function loopBackground(){if(!enabled||!background||pageHidden)return;if(bgMedia){bgMedia.play()?.catch(()=>{});return;}const tracks={童梦:0,青葱:1,求索:2,山河:1,岁华:2,归田:2};bgIndex=tracks[background]??1;const token=++bgToken,a=player('background',TRACKS[bgIndex].src);bgMedia=a;a.loop=true;applyVolume();const fail=()=>{if(bgMedia!==a||token!==bgToken)return;clearTimeout(bgLoadTimer);bgLoadTimer=null;a.pause();a.removeAttribute('src');bgMedia=null;if(!timer)loopFallback();window.dispatchEvent(new CustomEvent('qingyun-audio-warning',{detail:'完整音乐暂时无法载入，已切换备用配乐，游戏可继续。'}));};a.onplaying=()=>{if(token===bgToken){clearTimeout(bgLoadTimer);bgLoadTimer=null;}};a.onerror=fail;bgLoadTimer=setTimeout(fail,8000);a.play()?.catch(fail);}
function loopFallback(){if(!enabled||!background||pageHidden)return;const motifs={童梦:[0,7,4,7,12,7,4,0],青葱:[0,4,7,9,7,4,2,0],求索:[0,2,7,4,9,7,4,2],山河:[0,7,12,9,7,4,7,0],岁华:[0,4,7,4,2,0,-5,0],归田:[0,7,4,2,0,-5,2,0]},notes=motifs[background]||motifs.童梦;notes.forEach((n,i)=>tone(n,i*.65,.95,'background','sine',.05,background==='童梦'?329.63:196));timer=setTimeout(()=>{timer=null;loopFallback();},5500);}
function enqueue(job){if(!enabled)return Promise.resolve({muted:true});return new Promise((resolve,reject)=>{queue.push({...job,resolve,reject});drain();});}
export const playMilestone=type=>enqueue({type,bus:'milestone'});
export const playAnnouncement=item=>enqueue({...item,bus:'milestone'});
export const playHint=(positive,stage='成年')=>enqueue({type:'hint',positive,stage,bus:'hint'});
async function drain(){if(busy||!enabled||pageHidden||!queue.length)return;busy=true;applyVolume();const job=queue.shift(),own=generation;try{init();await resumeContext();if(job.type==='hint'){const key=job.stage+'-'+(job.positive?'positive':'negative'),url=localFiles[key]||sources[key];if(url){await playExternal(url);job.resolve({original:true});}else{await synth(job);job.resolve({fallback:true});}}else{await Promise.all([synth(job),job.text?speak(job.text):Promise.resolve()]);job.resolve({});}}catch(e){job.reject(e);}finally{if(own===generation){busy=false;applyVolume();drain();}}}
let finishExternal=null,finishSynth=null;
